1	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
2	import { useTreeStore } from "@/hooks/useTreeStore";
3	import { formatDate } from "@/utils/dateUtils";
4	import {
5	  Dialog,
6	  DialogContent,
7	  DialogDescription,
8	  DialogHeader,
9	  DialogTitle,
10	} from "@/components/ui/dialog";
11	import { Button } from "@/components/ui/button";
12	import { Input } from "@/components/ui/input";
13	import {
14	  Select,
15	  SelectContent,
16	  SelectItem,
17	  SelectTrigger,
18	  SelectValue,
19	} from "@/components/ui/select";
20	import {
21	  Popover,
22	  PopoverContent,
23	  PopoverTrigger,
24	} from "@/components/ui/popover";
25	import {
26	  Command,
27	  CommandEmpty,
28	  CommandGroup,
29	  CommandInput,
30	  CommandItem,
31	  CommandList,
32	} from "@/components/ui/command";
33	import { Badge } from "@/components/ui/badge";
34	import { Switch } from "@/components/ui/switch";
35	import {
36	  AlertDialog,
37	  AlertDialogAction,
38	  AlertDialogCancel,
39	  AlertDialogContent,
40	  AlertDialogDescription,
41	  AlertDialogFooter,
42	  AlertDialogHeader,
43	  AlertDialogTitle,
44	} from "@/components/ui/alert-dialog";
45	import {
46	  Check,
47	  ChevronsUpDown,
48	  Copy,
49	  Crown,
50	  EyeOff,
51	  Globe,
52	  Link,
53	  UserPlus,
54	  X,
55	} from "lucide-react";
56	import { useTreeSharingStore } from "@/hooks/useTreeSharingStore";
57	import { cn } from "@/lib/utils";
58	import {
59	  LinkedShareTree,
60	  RESTRICTABLE_DOMAINS,
61	  ShareCandidate,
62	  ShareRole,
63	  Tree,
64	  TreeAccess,
65	  TreeInvitation,
66	} from "@/types/tree";
67	import { toast } from "sonner";
68	import { useTranslation } from "react-i18next";
69	import { useFeature } from "@/hooks/useAuthStore";
70	
71	type Props = {
72	  tree: Tree;
73	  isOpen: boolean;
74	  onClose: () => void;
75	  onTreeUpdated?: (tree: Tree) => void;
76	};
77	
78	type StagedUser = ShareCandidate & { role: ShareRole };
79	
80	export const ShareTreeDialog = ({
81	  tree,
82	  isOpen,
83	  onClose,
84	  onTreeUpdated,
85	}: Props) => {
86	  const { t } = useTranslation(undefined, { keyPrefix: "dialog.share-tree" });
87	  const sharingInvitesEnabled = useFeature("sharing_invites");
88	  const treeLinksEnabled = useFeature("tree_links");
89	  const isOwner = tree.role === "owner";
90	
91	  // Hold the latest tree props so the open-time effect can initialize from them
92	  // without re-running (and re-fetching) when the tree object changes while the
93	  // dialog is already open — e.g. after toggling public access, which otherwise
94	  // flickers the dialog as the confirmation closes (#517).
95	  const treeRef = useRef(tree);
96	  treeRef.current = tree;
97	
98	  const access = useTreeSharingStore((state) => state.access);
99	  const candidates = useTreeSharingStore((state) => state.candidates);
100	  const invitations = useTreeSharingStore((state) => state.invitations);
101	  const linkedTrees = useTreeSharingStore((state) => state.linkedTrees);
102	  const loadSharing = useTreeSharingStore((state) => state.load);
103	  const grantAccess = useTreeSharingStore((state) => state.grantAccess);
104	  const revokeAccess = useTreeSharingStore((state) => state.revokeAccess);
105	  const updateMemberRestrictions = useTreeSharingStore(
106	    (state) => state.updateMemberRestrictions,
107	  );
108	  const transferOwnership = useTreeSharingStore((state) => state.transferOwnership);
109	  const revertTransfer = useTreeSharingStore((state) => state.revertTransfer);
110	  const createInvitation = useTreeSharingStore((state) => state.createInvitation);
111	  const revokeInvitation = useTreeSharingStore((state) => state.revokeInvitation);
112	  const setPublicAccess = useTreeSharingStore((state) => state.setPublicAccess);
113	  const setPublicPassword = useTreeSharingStore((state) => state.setPublicPassword);
114	  const getLinkedShareTrees = useTreeSharingStore(
115	    (state) => state.getLinkedShareTrees,
116	  );
117	  const grantAccessBatch = useTreeSharingStore((state) => state.grantAccessBatch);
118	  const revokeAccessBatch = useTreeSharingStore(
119	    (state) => state.revokeAccessBatch,
120	  );
121	  const [staged, setStaged] = useState<StagedUser[]>([]);
122	  const [pickerOpen, setPickerOpen] = useState(false);
123	  const [transferTo, setTransferTo] = useState("");
124	  const [confirmTransferOpen, setConfirmTransferOpen] = useState(false);
125	  const [retainAccess, setRetainAccess] = useState(false);
126	  const [retainRole, setRetainRole] = useState<ShareRole>("viewer");
127	
128	  // Invitations state
129	  const [inviteEmail, setInviteEmail] = useState("");
130	  const [inviteRole, setInviteRole] = useState<ShareRole>("editor");
131	  const [inviteExpiry, setInviteExpiry] = useState<string>("never");
132	  const [creatingInvite, setCreatingInvite] = useState(false);
133	
134	  // Public access state
135	  const [publicRole, setPublicRole] = useState<"viewer" | null>(
136	    tree.public_role ?? null,
137	  );
138	  const [confirmPublicOpen, setConfirmPublicOpen] = useState(false);
139	  const [pendingPublicRole, setPendingPublicRole] = useState<"viewer" | null>(
140	    null,
141	  );
142	  const [publicPasswordProtected, setPublicPasswordProtected] =
143	    useState<boolean>(tree.public_password_protected ?? false);
144	  const [publicPasswordInput, setPublicPasswordInput] = useState("");
145	  const publicPasswordError = useMemo(() => {
146	    if (!publicPasswordInput) return null;
147	    if (publicPasswordInput.length < 8) {
148	      return t("public.password.too-short");
149	    }
150	    if (new TextEncoder().encode(publicPasswordInput).length > 72) {
151	      return t("public.password.too-long");
152	    }
153	    return null;
154	  }, [publicPasswordInput, t]);
155	
156	  // Linked trees (issue #537): grant/revoke access on linked trees together
157	  // with the anchor tree, as a convenience batch operation.
158	  const [shareLinkedToo, setShareLinkedToo] = useState(false);
159	  const [selectedLinkedIds, setSelectedLinkedIds] = useState<Set<string>>(
160	    new Set(),
161	  );
162	  const [revokeLinkedOpen, setRevokeLinkedOpen] = useState(false);
163	  const [revokeLinkedCandidates, setRevokeLinkedCandidates] = useState<
164	    LinkedShareTree[]
165	  >([]);
166	  const [revokeLinkedSelectedIds, setRevokeLinkedSelectedIds] = useState<
167	    Set<string>
168	  >(new Set());
169	  const [revokeTarget, setRevokeTarget] = useState<{
170	    userId: string;
171	    username: string;
172	  } | null>(null);
173	
174	  const manageableLinkedTrees = useMemo(
175	    () => linkedTrees.filter((lt) => lt.manageable),
176	    [linkedTrees],
177	  );
178	  const nonManageableLinkedTrees = useMemo(
179	    () => linkedTrees.filter((lt) => !lt.manageable),
180	    [linkedTrees],
181	  );
182	
183	  // Any active user other than the current owner is an eligible new owner:
184	  // existing members plus the share candidates (users without access yet).
185	  const transferTargets = useMemo(
186	    () =>
187	      [
188	        ...access
189	          .filter((a) => a.role !== "owner")
190	          .map((a) => ({ user_id: a.user_id, username: a.username })),
191	        ...candidates,
192	      ].sort((a, b) => a.username.localeCompare(b.username)),
193	    [access, candidates],
194	  );
195	
196	  const reload = useCallback(async () => {
197	    await loadSharing(tree.id, {
198	      includeInvitations: sharingInvitesEnabled && isOwner,
199	      includeLinkedTrees: treeLinksEnabled && isOwner,
200	    });
201	  }, [tree.id, sharingInvitesEnabled, isOwner, treeLinksEnabled, loadSharing]);
202	
203	  useEffect(() => {
204	    if (isOpen) {
205	      setStaged([]);
206	      setTransferTo("");
207	      setRetainAccess(false);
208	      setRetainRole("viewer");
209	      setInviteEmail("");
210	      setInviteRole("editor");
211	      setInviteExpiry("never");
212	      setPublicRole(treeRef.current.public_role ?? null);
213	      setPublicPasswordProtected(
214	        treeRef.current.public_password_protected ?? false,
215	      );
216	      setPublicPasswordInput("");
217	      setShareLinkedToo(false);
218	      setSelectedLinkedIds(new Set());
219	      setRevokeLinkedOpen(false);
220	      setRevokeLinkedCandidates([]);
221	      setRevokeLinkedSelectedIds(new Set());
222	      setRevokeTarget(null);
223	      void reload();
224	    }
225	  }, [isOpen, reload]);
226	
227	  // Default every manageable linked tree to checked whenever the list (re)loads.
228	  useEffect(() => {
229	    setSelectedLinkedIds(
230	      new Set(manageableLinkedTrees.map((lt) => lt.tree_id)),
231	    );
232	  }, [manageableLinkedTrees]);
233	
234	  const toggleStaged = (candidate: ShareCandidate) => {
235	    setStaged((prev) =>
236	      prev.some((s) => s.user_id === candidate.user_id)
237	        ? prev.filter((s) => s.user_id !== candidate.user_id)
238	        : [...prev, { ...candidate, role: "editor" }],
239	    );
240	  };
241	
242	  const setStagedRole = (userId: string, role: ShareRole) => {
243	    setStaged((prev) =>
244	      prev.map((s) => (s.user_id === userId ? { ...s, role } : s)),
245	    );
246	  };
247	
248	  const handleShare = async () => {
249	    const includeLinked = shareLinkedToo && selectedLinkedIds.size > 0;
250	    try {
251	      for (const s of staged) {
252	        if (includeLinked) {
253	          await grantAccessBatch(
254	            tree.id,
255	            s.username,
256	            s.role,
257	            [tree.id, ...selectedLinkedIds],
258	          );
259	        } else {
260	          await grantAccess(tree.id, s.username, s.role);
261	        }
262	      }
263	      setStaged([]);
264	      setShareLinkedToo(false);
265	      await reload();
266	      toast.success(t("shared"));
267	    } catch (err) {
268	      console.error(err);
269	      toast.error(t("share-error"));
270	    }
271	  };
272	
273	  const handleRoleChange = async (member: TreeAccess, role: ShareRole) => {
274	    try {
275	      const updated = await grantAccess(
276	        tree.id,
277	        member.username,
278	        role,
279	      );
280	      useTreeSharingStore.setState({ access: updated });
281	    } catch (err) {
282	      console.error(err);
283	      toast.error(t("share-error"));
284	    }
285	  };
286	
287	  const handleRestrictionToggle = async (
288	    member: TreeAccess,
289	    domain: string,
290	    accessible: boolean,
291	  ) => {
292	    const current = member.restrictions ?? [];
293	    const next = accessible
294	      ? current.filter((d) => d !== domain)
295	      : [...new Set([...current, domain])];
296	    try {
297	      const updated = await updateMemberRestrictions(
298	        tree.id,
299	        member.user_id,
300	        next,
301	      );
302	      useTreeSharingStore.setState({ access: updated });
303	    } catch (err) {
304	      console.error(err);
305	      toast.error(t("restrictions-error"));
306	    }
307	  };
308	
309	  const handleRevoke = async (userId: string, username: string) => {
310	    if (treeLinksEnabled && manageableLinkedTrees.length > 0) {
311	      try {
312	        const linked = await getLinkedShareTrees(
313	          tree.id,
314	          username,
315	        );
316	        const revocable = linked.filter(
317	          (lt) =>
318	            lt.manageable &&
319	            (lt.target_role === "viewer" || lt.target_role === "editor"),
320	        );
321	        if (revocable.length > 0) {
322	          setRevokeLinkedCandidates(revocable);
323	          setRevokeLinkedSelectedIds(
324	            new Set(revocable.map((lt) => lt.tree_id)),
325	          );
326	          setRevokeTarget({ userId, username });
327	          setRevokeLinkedOpen(true);
328	          return;
329	        }
330	      } catch (err) {
331	        // Fall through to a plain revoke if the linked-trees lookup fails —
332	        // it's a convenience add-on, not a prerequisite for revoking access.
333	        console.error(err);
334	      }
335	    }
336	    await revokeAnchorOnly(userId);
337	  };
338	
339	  const revokeAnchorOnly = async (userId: string) => {
340	    try {
341	      await revokeAccess(tree.id, userId);
342	      await reload();
343	    } catch (err) {
344	      console.error(err);
345	      toast.error(t("revoke-error"));
346	    }
347	  };
348	
349	  const handleRevokeLinkedConfirm = async () => {
350	    if (!revokeTarget) return;
351	    try {
352	      await revokeAccessBatch(tree.id, revokeTarget.userId, [
353	        tree.id,
354	        ...revokeLinkedSelectedIds,
355	      ]);
356	      setRevokeLinkedOpen(false);
357	      setRevokeTarget(null);
358	      await reload();
359	    } catch (err) {
360	      console.error(err);
361	      toast.error(t("revoke-error"));
362	    }
363	  };
364	
365	  const handleRevokeAnchorOnly = async () => {
366	    if (!revokeTarget) return;
367	    setRevokeLinkedOpen(false);
368	    await revokeAnchorOnly(revokeTarget.userId);
369	    setRevokeTarget(null);
370	  };
371	
372	  const handleRevokeLinkedOpenChange = (open: boolean) => {
373	    setRevokeLinkedOpen(open);
374	    if (!open) {
375	      setRevokeTarget(null);
376	    }
377	  };
378	
379	  const toggleRevokeLinkedId = (treeId: string) => {
380	    setRevokeLinkedSelectedIds((prev) => {
381	      const next = new Set(prev);
382	      if (next.has(treeId)) {
383	        next.delete(treeId);
384	      } else {
385	        next.add(treeId);
386	      }
387	      return next;
388	    });
389	  };
390	
391	  const toggleSelectedLinkedId = (treeId: string) => {
392	    setSelectedLinkedIds((prev) => {
393	      const next = new Set(prev);
394	      if (next.has(treeId)) {
395	        next.delete(treeId);
396	      } else {
397	        next.add(treeId);
398	      }
399	      return next;
400	    });
401	  };
402	
403	  const showUndoToast = (
404	    treeId: string,
405	    treeName: string,
406	    username: string,
407	    undoAvailableUntil: string,
408	  ) => {
409	    const deadline = new Date(undoAvailableUntil).getTime();
410	    const toastId = `transfer-undo-${treeId}`;
411	    let cancelled = false;
412	
413	    const renderToast = () => {
414	      if (cancelled) return;
415	      const remaining = Math.max(0, Math.round((deadline - Date.now()) / 1000));
416	      if (remaining <= 0) {
417	        toast.dismiss(toastId);
418	        return;
419	      }
420	      toast(t("transfer-undo-title"), {
421	        id: toastId,
422	        description: t("transfer-undo-description", {
423	          name: treeName,
424	          username,
425	        }),
426	        duration: deadline - Date.now() + 500,
427	        onDismiss: () => {
428	          cancelled = true;
429	        },
430	        onAutoClose: () => {
431	          cancelled = true;
432	        },
433	        action: {
434	          label: t("transfer-undo-button", { seconds: remaining }),
435	          onClick: () => {
436	            cancelled = true;
437	            void revertTransfer(treeId)
438	              .then(() => {
439	                toast.dismiss(toastId);
440	                toast.success(t("transfer-reverted"));
441	                void useTreeStore.getState().loadTrees();
442	              })
443	              .catch(() => {
444	                cancelled = false;
445	                toast.error(t("transfer-revert-error"));
446	              });
447	          },
448	        },
449	      });
450	      setTimeout(renderToast, 1000);
451	    };
452	    renderToast();
453	  };
454	
455	  const handleTransfer = async () => {
456	    try {
457	      const result = await transferOwnership(
458	        tree.id,
459	        transferTo,
460	        retainAccess ? retainRole : undefined,
461	      );
462	      setConfirmTransferOpen(false);
463	      setTransferTo("");
464	      await useTreeStore.getState().loadTrees();
465	      onClose();
466	      if (result.undo_available_until) {
467	        showUndoToast(
468	          tree.id,
469	          tree.name,
470	          transferTo,
471	          result.undo_available_until,
472	        );
473	      } else {
474	        toast.success(t("transfer-success"));
475	      }
476	    } catch (err) {
477	      console.error(err);
478	      toast.error(t("transfer-error"));
479	    }
480	  };
481	
482	  const handleCreateInvite = async () => {
483	    setCreatingInvite(true);
484	    try {
485	      const expiresInDays =
486	        inviteExpiry === "never" ? undefined : inviteExpiry === "7" ? 7 : 30;
487	      await createInvitation(tree.id, {
488	        email: inviteEmail || undefined,
489	        role: inviteRole,
490	        expiresInDays,
491	      });
492	      setInviteEmail("");
493	      setInviteRole("editor");
494	      setInviteExpiry("never");
495	      await reload();
496	    } catch (err) {
497	      console.error(err);
498	      toast.error(t("invites.create-error"));
499	    } finally {
500	      setCreatingInvite(false);
501	    }
502	  };
503	
504	  const handleRevokeInvite = async (invitationId: string) => {
505	    try {
506	      await revokeInvitation(tree.id, invitationId);
507	      await reload();
508	    } catch (err) {
509	      console.error(err);
510	      toast.error(t("invites.revoke-error"));
511	    }
512	  };
513	
514	  const handleCopyLink = (token: string) => {
515	    const url = `${window.location.origin}/#invite=${token}`;
516	    void navigator.clipboard.writeText(url);
517	    toast.success(t("invites.link-copied"));
518	  };
519	
520	  const handlePublicToggle = (checked: boolean) => {
521	    setPendingPublicRole(checked ? "viewer" : null);
522	    setConfirmPublicOpen(true);
523	  };
524	
525	  const handlePublicOpenChange = (open: boolean) => {
526	    setConfirmPublicOpen(open);
527	    if (!open) {
528	      setPendingPublicRole(null);
529	    }
530	  };
531	
532	  const handleTransferOpenChange = (open: boolean) => {
533	    setConfirmTransferOpen(open);
534	    if (!open) {
535	      setTransferTo("");
536	    }
537	  };
538	
539	  const handlePublicConfirm = async () => {
540	    try {
541	      const updated = await setPublicAccess(
542	        tree.id,
543	        pendingPublicRole,
544	      );
545	      setPublicRole(updated.public_role ?? null);
546	      // Disabling public access clears the password server-side.
547	      setPublicPasswordProtected(updated.public_password_protected ?? false);
548	      onTreeUpdated?.(updated);
549	      setConfirmPublicOpen(false);
550	    } catch (err) {
551	      console.error(err);
552	      toast.error(t("public.error"));
553	      setConfirmPublicOpen(false);
554	    }
555	  };
556	
557	  const handleSetPublicPassword = async () => {
558	    if (publicPasswordError) return;
559	    try {
560	      const updated = await setPublicPassword(
561	        tree.id,
562	        publicPasswordInput,
563	      );
564	      setPublicPasswordProtected(updated.public_password_protected ?? false);
565	      setPublicPasswordInput("");
566	      onTreeUpdated?.(updated);
567	      toast.success(t("public.password.saved"));
568	    } catch (err) {
569	      console.error(err);
570	      toast.error(t("public.password.error"));
571	    }
572	  };
573	
574	  const handleRemovePublicPassword = async () => {
575	    try {
576	      const updated = await setPublicPassword(
577	        tree.id,
578	        null,
579	      );
580	      setPublicPasswordProtected(updated.public_password_protected ?? false);
581	      setPublicPasswordInput("");
582	      onTreeUpdated?.(updated);
583	      toast.success(t("public.password.removed"));
584	    } catch (err) {
585	      console.error(err);
586	      toast.error(t("public.password.error"));
587	    }
588	  };
589	
590	  const inviteStatusBadge = (status: TreeInvitation["status"]) => {
591	    const variants: Record<
592	      TreeInvitation["status"],
593	      "default" | "secondary" | "destructive" | "outline"
594	    > = {
595	      pending: "default",
596	      accepted: "secondary",
597	      revoked: "destructive",
598	      expired: "outline",
599	    };
600	    return (
601	      <Badge variant={variants[status]}>{t(`invites.status-${status}`)}</Badge>
602	    );
603	  };
604	
605	  const publicLink = `${window.location.origin}/#public=${tree.id}`;
606	
607	  return (
608	    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
609	      <DialogContent
610	        className="max-h-[90vh] min-w-[600px] overflow-y-auto"
611	        onInteractOutside={(e) => {
612	          // The public-access / transfer confirmations render as sibling
613	          // AlertDialog portals. Radix treats a pointer-down or focus change
614	          // inside them as an interaction "outside" this dialog and would
615	          // dismiss it — closing the share dialog on cancel, or setting the
616	          // tree to null then back on confirm (replaying the open animation).
617	          // Keep the share dialog open for any interaction originating from a
618	          // nested alert dialog. (#517)
619	          const target = e.target as Element | null;
620	          if (target?.closest?.('[data-slot^="alert-dialog"]')) {
621	            e.preventDefault();
622	          }
623	        }}
624	      >
625	        <DialogHeader>
626	          <DialogTitle>{t("title", { name: tree.name })}</DialogTitle>
627	          <DialogDescription>{t("description")}</DialogDescription>
628	        </DialogHeader>
629	
630	        {/* People who already have access */}
631	        <div className="space-y-2">
632	          <p className="text-sm font-medium">{t("current-access")}</p>
633	          {access.map((a) => (
634	            <div
635	              key={a.user_id}
636	              className="flex items-center justify-between rounded-md border p-2"
637	            >
638	              <span className="text-sm font-medium">{a.username}</span>
639	              {a.role === "owner" ? (
640	                <Badge variant="secondary">{t("role-owner")}</Badge>
641	              ) : (
642	                <div className="flex items-center gap-2">
643	                  {isOwner && (
644	                    <Popover>
645	                      <PopoverTrigger asChild>
646	                        <Button
647	                          variant="ghost"
648	                          size="sm"
649	                          title={t("restrictions-button")}
650	                        >
651	                          <EyeOff className="h-4 w-4" />
652	                          {(a.restrictions?.length ?? 0) > 0 && (
653	                            <Badge
654	                              variant="secondary"
655	                              className="ml-1 h-4 px-1 text-xs"
656	                            >
657	                              {a.restrictions!.length}
658	                            </Badge>
659	                          )}
660	                        </Button>
661	                      </PopoverTrigger>
662	                      <PopoverContent className="w-48 p-2" align="end">
663	                        <p className="mb-2 text-xs font-medium text-muted-foreground">
664	                          {t("restrictions-title")}
665	                        </p>
666	                        {RESTRICTABLE_DOMAINS.map((domain) => (
667	                          <div
668	                            key={domain}
